{"Document Name": ["CONTENT LICENSE AGREEMENT SUPPLEMENT TO THE EXCLUSIVE BROADCASTING AGREEMENT"], "Parties": ["CHINA ECONOMIC INFORMATION SERVICE OF XINHUA NEWS AGENCY", "CEIS", "XINHUA FINANCIAL NETWORK LIMITED", "XFN", "(collectively referred to as "PARTIES"; individually, a "PARTY")."], "Agreement Date": ["15TH DECEMBER 2001"], "Effective Date": ["EFFECTIVE DATE means 18 May 2000;"], "Expiration Date": [], "Renewal Term": [], "Notice Period To Terminate Renewal": [], "Governing Law": [], "Termination For Convenience": [], "Anti-Assignment": [], "Change Of Control": [], "Cap On Liability": [], "Uncapped Liability": [], "Minimum Commitment": [], "Exclusivity": ["Exclusive Rights in the Territory: CEIS hereby grants XFN and its Affiliates an exclusive license (free of all third-party liens, claims and encumbrances) to, and to permit others to, during the Term in the Territory:

(a) store or cache the Content in one or more host computers controlled directly or indirectly by XFN or its Affiliates;

(b) adapt, translate, modify, reproduce, copy, amend, revise or encode the Content; and

(c) publish, broadcast, distribute, re-distribute, transmit, display, make available to the public or otherwise exploit the Content in any manner by any device or in media now or hereafter known."], "Audit Rights": []}

{"Document Name": [], "Parties": [], "Agreement Date": [], "Effective Date": [], "Expiration Date": [], "Renewal Term": [], "Notice Period To Terminate Renewal": [], "Governing Law": [], "Termination For Convenience": [], "Anti-Assignment": [], "Change Of Control": [], "Cap On Liability": ["Under no circumstances shall Equifax be required to pay, with respect to the transfer of, acquisition of, or procuring or securing of Third Party Agreements or Third Party Use Rights, costs, fees or expenses exceed the sum of the "totals" identified on this Exhibit C and Exhibit D, except that:

(a) Equifax shall be responsible for paying any sales, transfer or VAT taxes directly associated with transferring and/or acquiring such licenses, and the parties agree that such taxes are not included in the maximum fees/costs identified above; and

(b) Equifax agrees to pay (i) any fees and costs, not to exceed $16,500, in connection with obtaining any consents necessary with respect to the Pitney Bowes DocSense software products, LPC Finalist and Streamweaver, and (ii) any fees and costs, not to exceed $120,000, in connection with obtaining any consents necessary with respect to SAS Institute's software products, SAS Base, SAS Connect, SAS Echo, SAS Stat and SAS Warehouse. Such amounts to be paid shall be additional to the amounts required to be paid otherwise under this Exhibit C or Exhibit D."], "Uncapped Liability": [], "Minimum Commitment": [], "Exclusivity": [], "Audit Rights": []}
